<?php declare(strict_types=1);require_once __DIR__.'/../config/config.php';require_once __DIR__.'/../config/database.php';require_once __DIR__.'/includes/auth.php';$db=db();$from=$_GET['from']??date('Y-01-01');$to=$_GET['to']??date('Y-m-d');$q=$db->prepare("SELECT invoice_number,issue_date,due_date,status,currency,total,amount_paid,balance_due FROM invoices WHERE issue_date BETWEEN ? AND ? ORDER BY issue_date DESC");$q->execute([$from,$to]);if(($_GET['format']??'')==='csv'){header('Content-Type:text/csv');header('Content-Disposition:attachment; filename="financial-report.csv"');$out=fopen('php://output','w');fputcsv($out,['Invoice','Issue Date','Due Date','Status','Currency','Total','Paid','Balance']);while($r=$q->fetch(PDO::FETCH_ASSOC))fputcsv($out,$r);fclose($out);exit;}?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Management Report</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"></head><body class="bg-light"><main class="container py-4"><h1 class="h3">Management Report</h1><form class="row g-2 mb-3"><div class="col-md-4"><input class="form-control" type="date" name="from" value="<?=htmlspecialchars($from,ENT_QUOTES,'UTF-8')?>"></div><div class="col-md-4"><input class="form-control" type="date" name="to" value="<?=htmlspecialchars($to,ENT_QUOTES,'UTF-8')?>"></div><div class="col-md-2"><button class="btn btn-dark w-100">Filter</button></div><div class="col-md-2"><input type="hidden" name="format" value="csv"><button class="btn btn-outline-dark w-100">CSV</button></div></form><div class="card"><div class="card-body"><p>Use the filters above to generate a management-ready invoice and receivables export.</p></div></div></main></body></html>